// HasStageRuns applies the HasEdge predicate on the "stage_runs" edge.
func HasStageRuns() predicate.Task {
	return predicate.Task(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, StageRunsTable, StageRunsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasStageRunsWith applies the HasEdge predicate on the "stage_runs" edge with a given conditions (other predicates).
func HasStageRunsWith(preds ...predicate.StageRun) predicate.Task {
	return predicate.Task(func(s *sql.Selector) {
		step := newStageRunsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

